import {el,button,announce} from './ui.js';
export function openArticle(scam) { const dialog=document.getElementById('article-dialog');const content=document.getElementById('article-content');content.replaceChildren(el('span','tag',scam.category));const title=el('h2','',scam.title);title.id='article-title';content.append(title,el('p','',scam.summary));[['Warning signs',scam.warningSigns],['Safer action',scam.prevention],['If you have been targeted',scam.nextSteps]].forEach(([label,items])=>{content.append(el('h3','',label));const ul=el('ul');items.forEach(t=>ul.append(el('li','',t)));content.append(ul);});if(!dialog.open)dialog.showModal(); }
export function mountLibrary(host,scams) { host.innerHTML='<div class="library-tools"><label class="search-wrap"><span aria-hidden="true">⌕</span><span class="sr-only">Search scam topics</span><input type="search" placeholder="Search scams, warning signs, or keywords…" maxlength="100"></label></div><div class="chips" aria-label="Filter by category"></div><p class="library-count" role="status"></p><div class="cards"></div>';let category='All topics';const input=host.querySelector('input');const chips=host.querySelector('.chips');const grid=host.querySelector('.cards');const count=host.querySelector('.library-count');['All topics','Payments','Messages','Jobs','Shopping / Delivery','Impersonation','Malware','Adware'].forEach(name=>{const b=button(name,'chip',()=>{category=name;render();});b.dataset.category=name;chips.append(b);});function render(){chips.querySelectorAll('button').forEach(b=>{b.classList.toggle('active',b.dataset.category===category);b.setAttribute('aria-pressed',String(b.dataset.category===category));});const query=input.value.trim().toLowerCase();const found=scams.filter(s=>(category==='All topics'||s.category===category)&&[s.title,s.summary,s.keywords,...s.warningSigns].join(' ').toLowerCase().includes(query));count.textContent=`${found.length} ${found.length===1?'topic':'topics'} to explore`;grid.replaceChildren();if(!found.length){const empty=el('div','empty');empty.append(el('h3','','No matching topics'),el('p','','Try “UPI”, “OTP” or “delivery”, or choose a different category.'),button('Clear search & filters','button secondary',()=>{input.value='';category='All topics';render();input.focus();}));grid.append(empty);return;}found.forEach(s=>{const card=el('article','card');const top=el('div','card-top');top.append(el('span','icon-box',s.symbol),el('span','tag',s.category));card.append(top,el('h3','',s.title),el('p','',s.summary),button('Learn the warning signs  →','card-link reset-button',()=>openArticle(s)));grid.append(card);});}input.addEventListener('input',render);render(); }
